import os

for root, dirs, files in os.walk('.'):
    for f in files:
        path = os.path.join(root, f)
        if f.endswith(('.txt', '.eml', '.docx', '.xlsx', '.pdf')):
            try:
                # check if file mentions Section 2 or bond or estimate
                if f.endswith('.eml'):
                    with open(path, errors='ignore') as fp:
                        content = fp.read()
                        if 'section 2' in content.lower() or 'estimate' in content.lower():
                            print(f'EML match: {path}')
                elif f.endswith('.docx'):
                    import docx
                    d = docx.Document(path)
                    text = ' '.join(p.text for p in d.paragraphs)
                    if 'section 2' in text.lower():
                        print(f'DOCX match: {path}')
            except:
                pass
