import os, fitz, openpyxl

for root, dirs, files in os.walk('.'):
    for f in files:
        p = os.path.join(root, f)
        if f.endswith('.pdf'):
            try:
                doc = fitz.open(p)
                for i, page in enumerate(doc):
                    t = page.get_text()
                    if 'S-15' in t or 's-15' in t:
                        print(f'{p} [p.{i+1}]:')
                        for line in t.split('\n'):
                            if 's-15' in line.lower() or 'inflow' in line.lower() or 'line b' in line.lower():
                                print('  ', line.strip())
            except:
                pass
        elif f.endswith('.xlsx'):
            try:
                wb = openpyxl.load_workbook(p, data_only=True)
                for s in wb.sheetnames:
                    ws = wb[s]
                    for r in range(1, ws.max_row+1):
                        row_str = ' '.join(str(ws.cell(r, c).value) for c in range(1, ws.max_column+1))
                        if 'S-15' in row_str or 's-15' in row_str:
                            print(f'{p} [{s} R{r}]: {row_str[:120]}')
            except:
                pass
"

